import{_ as e,c as t,o as d,a2 as o}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"Forms Overview","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview"},"headers":[],"relativePath":"guide/form-inputs/overview.md","filePath":"guide/form-inputs/overview.md","lastUpdated":1777448730000}'),r={name:"guide/form-inputs/overview.md"},a=o(`<h1 id="forms-overview" tabindex="-1">Forms Overview <a class="header-anchor" href="#forms-overview" aria-label="Permalink to &quot;Forms Overview&quot;">​</a></h1><p>Modularous forms are schema-driven. The backend defines inputs; Hydrates transform them into a frontend schema; Vue components consume and render them.</p><h2 id="what-are-hydrates" tabindex="-1">What Are Hydrates? <a class="header-anchor" href="#what-are-hydrates" aria-label="Permalink to &quot;What Are Hydrates?&quot;">​</a></h2><p><strong>Hydrates</strong> are PHP classes that sit between your module config and the frontend form. Each input type has its own Hydrate class that transforms a raw config array into a well-defined schema object the Vue side can render.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Module config  →  InputHydrator  →  XxxHydrate  →  schema  →  Vue component</span></span>
<span class="line"><span>{ type: &#39;checklist&#39;, ... }              ↓          { type: &#39;input-checklist&#39;, items: [...], ... }</span></span>
<span class="line"><span>                               resolves class name</span></span></code></pre></div><h3 id="what-they-do" tabindex="-1">What they do? <a class="header-anchor" href="#what-they-do" aria-label="Permalink to &quot;What they do?&quot;">​</a></h3><ul><li><strong>Set defaults</strong> — fill in missing keys (e.g. <code>itemValue: &#39;id&#39;</code>, <code>itemTitle: &#39;name&#39;</code>)</li><li><strong>Change the type</strong> — convert <code>&#39;checklist&#39;</code> (config alias) → <code>&#39;input-checklist&#39;</code> (frontend type)</li><li><strong>Load records</strong> — call a repository or connector to populate <code>items</code> for selectable inputs</li><li><strong>Apply rules</strong> — parse <code>rules</code> string and add CSS classes (e.g. <code>required</code>)</li><li><strong>Strip backend keys</strong> — remove <code>route</code>, <code>model</code>, <code>repository</code>, <code>cascades</code>, <code>connector</code> before the schema reaches the frontend</li></ul><h3 id="why-they-exist" tabindex="-1">Why they exist? <a class="header-anchor" href="#why-they-exist" aria-label="Permalink to &quot;Why they exist?&quot;">​</a></h3><p>The Hydrate layer decouples module config syntax from frontend schema syntax. You write concise config in PHP; the Hydrate handles enrichment, fetching, and normalization. The frontend only ever sees a clean, complete schema object.</p><h3 id="resolution-rule" tabindex="-1">Resolution rule <a class="header-anchor" href="#resolution-rule" aria-label="Permalink to &quot;Resolution rule&quot;">​</a></h3><p><code>InputHydrator</code> resolves the class by: <code>studlyCase($input[&#39;type&#39;]) . &#39;Hydrate&#39;</code></p><table><thead><tr><th>Config <code>type</code></th><th>Resolved class</th></tr></thead><tbody><tr><td><code>checklist</code></td><td><code>ChecklistHydrate</code></td></tr><tr><td><code>select-scroll</code></td><td><code>SelectScrollHydrate</code></td></tr><tr><td><code>filepond-avatar</code></td><td><code>FilepondAvatarHydrate</code></td></tr></tbody></table><p>All Hydrate classes live in <code>src/Hydrates/Inputs/</code>.</p><h2 id="render-pipeline" tabindex="-1">Render Pipeline <a class="header-anchor" href="#render-pipeline" aria-label="Permalink to &quot;Render Pipeline&quot;">​</a></h2><p>Every Hydrate runs the same pipeline when <code>render()</code> is called:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setDefaults()     — apply $requirements defaults</span></span>
<span class="line"><span>hydrate()         — set output type, enrich schema</span></span>
<span class="line"><span>hydrateRecords()  — load items via repository/connector</span></span>
<span class="line"><span>hydrateRules()    — parse rules string, add CSS classes</span></span>
<span class="line"><span>Arr::except()     — strip backend-only keys</span></span></code></pre></div><h2 id="form-rendering-flow" tabindex="-1">Form Rendering Flow <a class="header-anchor" href="#form-rendering-flow" aria-label="Permalink to &quot;Form Rendering Flow&quot;">​</a></h2><ol><li><strong>Module config</strong> — define inputs in your module&#39;s <code>config.php</code></li><li><strong>Controller</strong> — <code>setupFormSchema()</code> calls <code>InputHydrator</code> before create/edit</li><li><strong>Inertia</strong> — hydrated schema + model are passed to the page</li><li><strong>Form.vue</strong> — receives <code>schema</code> and <code>modelValue</code>, uses <code>useForm</code></li><li><strong>FormBase</strong> — flattens schema + model into <code>flatCombinedArraySorted</code>, iterates over each field</li><li><strong>FormBaseField</strong> — renders each field by <code>obj.schema.type</code> via <code>mapTypeToComponent()</code></li><li><strong>Input components</strong> — receive schema props via <code>bindSchema(obj)</code></li></ol><h2 id="key-components" tabindex="-1">Key Components <a class="header-anchor" href="#key-components" aria-label="Permalink to &quot;Key Components&quot;">​</a></h2><table><thead><tr><th>Component</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Form.vue</strong></td><td>Top-level form; validation, submit, schema/model sync</td></tr><tr><td><strong>FormBase</strong></td><td>Iterates over flattened schema; grid layout, slots</td></tr><tr><td><strong>FormBaseField</strong></td><td>Renders a single field; resolves type → component</td></tr><tr><td><strong>CustomFormBase</strong></td><td>Wrapper with app-specific behavior</td></tr></tbody></table><h2 id="schema-structure" tabindex="-1">Schema Structure <a class="header-anchor" href="#schema-structure" aria-label="Permalink to &quot;Schema Structure&quot;">​</a></h2><p>Each field in the schema has:</p><ul><li><code>type</code> — Resolved to Vue component (e.g. <code>input-checklist</code>, <code>text</code>, <code>select</code>)</li><li><code>name</code> — Field name (binds to model)</li><li><code>label</code> — Display label</li><li><code>col</code> — Grid column span</li><li><code>rules</code> — Validation rules</li><li><code>default</code> — Default value</li></ul><p><strong>Backend-only keys</strong> (stripped before frontend): <code>route</code>, <code>model</code>, <code>repository</code>, <code>cascades</code>, <code>connector</code></p><h2 id="config-→-component-reference" tabindex="-1">Config → Component Reference <a class="header-anchor" href="#config-→-component-reference" aria-label="Permalink to &quot;Config → Component Reference&quot;">​</a></h2><table><thead><tr><th>Config type</th><th>Hydrate class</th><th>Output type</th><th>Vue component</th></tr></thead><tbody><tr><td><a href="/guide/form-inputs/input-assignment">assignment</a></td><td>AssignmentHydrate</td><td>input-assignment</td><td>VInputAssignment</td></tr><tr><td><a href="/guide/form-inputs/input-autocomplete">autocomplete</a></td><td>AutocompleteHydrate</td><td>select / input-select-scroll</td><td>v-autocomplete</td></tr><tr><td><a href="/guide/form-inputs/input-browser">browser</a></td><td>BrowserHydrate</td><td>input-browser</td><td>VInputBrowser</td></tr><tr><td><a href="/guide/form-inputs/input-chat">chat</a></td><td>ChatHydrate</td><td>input-chat</td><td>VInputChat</td></tr><tr><td><a href="/guide/form-inputs/input-checkbox">checkbox</a></td><td>CheckboxHydrate</td><td>checkbox</td><td>v-checkbox</td></tr><tr><td><a href="/guide/form-inputs/input-checklist">checklist</a></td><td>ChecklistHydrate</td><td>input-checklist</td><td>VInputChecklist</td></tr><tr><td><a href="/guide/form-inputs/input-checklist-group">checklist-group</a></td><td>ChecklistGroupHydrate</td><td>input-checklist-group</td><td>VInputChecklistGroup</td></tr><tr><td><a href="/guide/form-inputs/input-combobox">combobox</a></td><td>ComboboxHydrate</td><td>combobox / input-select-scroll</td><td>v-combobox</td></tr><tr><td><a href="/guide/form-inputs/input-comparison-table">comparison-table</a></td><td>ComparisonTableHydrate</td><td>input-comparison-table</td><td>VInputComparisonTable</td></tr><tr><td><a href="/guide/form-inputs/input-date">date</a></td><td>DateHydrate</td><td>input-date</td><td>VInputDate</td></tr><tr><td><a href="/guide/form-inputs/input-file">file</a></td><td>FileHydrate</td><td>input-file</td><td>VInputFile</td></tr><tr><td><a href="/guide/form-inputs/input-filepond-avatar">filepond-avatar</a></td><td>FilepondAvatarHydrate</td><td>input-filepond-avatar</td><td>VInputFilepondAvatar</td></tr><tr><td><a href="/guide/form-inputs/input-form-tabs">form-tabs</a></td><td>FormTabsHydrate</td><td>input-form-tabs</td><td>VInputFormTabs</td></tr><tr><td><a href="/guide/form-inputs/input-image">image</a></td><td>ImageHydrate</td><td>input-image</td><td>VInputImage</td></tr><tr><td><a href="/guide/form-inputs/input-json">json</a></td><td>JsonHydrate</td><td>group</td><td>(group layout)</td></tr><tr><td><a href="/guide/form-inputs/input-json-repeater">json-repeater</a></td><td>JsonRepeaterHydrate</td><td>input-repeater</td><td>VInputRepeater</td></tr><tr><td><a href="/guide/form-inputs/input-payment-service">payment-service</a></td><td>PaymentServiceHydrate</td><td>input-payment-service</td><td>VInputPaymentService</td></tr><tr><td><a href="/guide/form-inputs/input-price">price</a></td><td>PriceHydrate</td><td>input-price</td><td>VInputPrice</td></tr><tr><td><a href="/guide/form-inputs/input-process">process</a></td><td>ProcessHydrate</td><td>input-process</td><td>VInputProcess</td></tr><tr><td><a href="/guide/form-inputs/input-radio-group">radio-group</a></td><td>RadioGroupHydrate</td><td>input-radio-group</td><td>VInputRadioGroup</td></tr><tr><td><a href="/guide/form-inputs/input-repeater">repeater</a></td><td>RepeaterHydrate</td><td>input-repeater</td><td>VInputRepeater</td></tr><tr><td><a href="/guide/form-inputs/input-select-scroll">select-scroll</a></td><td>SelectScrollHydrate</td><td>input-select-scroll</td><td>VInputSelectScroll</td></tr><tr><td><a href="/guide/form-inputs/input-spread">spread</a></td><td>SpreadHydrate</td><td>input-spread</td><td>VInputSpread</td></tr><tr><td><a href="/guide/form-inputs/input-switch">switch</a></td><td>SwitchHydrate</td><td>input-switch</td><td>VInputSwitch</td></tr><tr><td><a href="/guide/form-inputs/input-tag">tag</a></td><td>TagHydrate</td><td>input-tag</td><td>VInputTag</td></tr><tr><td><a href="/guide/form-inputs/input-tagger">tagger</a></td><td>TaggerHydrate</td><td>input-tagger</td><td>VInputTagger</td></tr></tbody></table><h2 id="formbase-slots" tabindex="-1">FormBase Slots <a class="header-anchor" href="#formbase-slots" aria-label="Permalink to &quot;FormBase Slots&quot;">​</a></h2><p>FormBase provides slots for customization:</p><ul><li><code>form-top</code>, <code>form-bottom</code> — Form-level</li><li><code>{type}-top</code>, <code>{type}-bottom</code> — By schema type (e.g. <code>input-checklist-top</code>)</li><li><code>{key}-top</code>, <code>{key}-bottom</code> — By field name</li><li><code>{type}-item</code>, <code>{key}-item</code> — Override field rendering</li></ul><h2 id="adding-a-new-input" tabindex="-1">Adding a New Input <a class="header-anchor" href="#adding-a-new-input" aria-label="Permalink to &quot;Adding a New Input&quot;">​</a></h2><ol><li><strong>PHP</strong> — Create <code>src/Hydrates/Inputs/{Studly}Hydrate.php</code> extending <code>InputHydrate</code><ul><li>Set <code>$input[&#39;type&#39;] = &#39;input-{kebab}&#39;</code> in <code>hydrate()</code></li><li>Define <code>$requirements</code> for default schema keys</li></ul></li><li><strong>Vue</strong> — Create <code>vue/src/js/components/inputs/{Studly}.vue</code><ul><li>Use <code>useInput</code>, <code>makeInputProps</code>, <code>makeInputEmits</code> from <code>@/hooks</code></li><li>Component auto-registers as <code>VInput{Studly}</code> via <code>includeFormInputs</code> glob</li></ul></li><li><strong>Registry</strong> (optional) — Add to <code>hydrateTypeMap</code> in <code>registry.js</code> for explicit mapping</li></ol><p>See the <a href="/guide/console/generators/create-input-hydrate">create-input-hydrate</a> and <a href="/guide/console/generators/create-vue-input">create-vue-input</a> commands.</p>`,32),n=[a];function i(s,c,l,p,u,h){return d(),t("div",null,n)}const f=e(r,[["render",i]]);export{g as __pageData,f as default};
